import { sql } from "drizzle-orm"
import { customType, timestamp, uuid } from "drizzle-orm/pg-core"

/** UUIDv7 primary key generated by Postgres 18. */
export const id = () =>
  uuid("id")
    .primaryKey()
    .default(sql`uuidv7()`)

/** Primary key that is also the row's `entities.id`. */
export const entityPk = () => uuid("id").primaryKey()

export const timestamptz = (name: string) => timestamp(name, { withTimezone: true, mode: "date" })

export const createdAt = () => timestamptz("created_at").notNull().defaultNow()
export const updatedAt = () => timestamptz("updated_at").notNull().defaultNow()

/** Read-only full-text vector; the server registers a codec for it (see `@audit/platform`). */
export const tsvector = customType<{ data: string; driverData: string }>({
  dataType: () => "tsvector",
})

/**
 * Half-precision embedding vector of a fixed dimension (`halfvec(n)`). The dimension follows the
 * configured embedding model; the server registers no codec, values travel as pgvector text.
 */
export const halfvec = customType<{
  data: number[]
  driverData: string
  config: { dimensions: number }
}>({
  dataType: (config) => `halfvec(${config?.dimensions ?? 1536})`,
  toDriver: (value) => `[${value.join(",")}]`,
  fromDriver: (value) =>
    value
      .slice(1, -1)
      .split(",")
      .map((part) => Number(part)),
})
